from collections import deque
def comps(g):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j] and (i,j) not in seen:
                c=g[i][j]; q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==c and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                out.append((c,cells))
    return out
def shape(cells):
    ys=[y for y,x in cells]; xs=[x for y,x in cells]
    m=min(ys),min(xs)
    return tuple(sorted((y-m[0],x-m[1]) for y,x in cells))
for name in ['Demo pair 1 input','Demo pair 1 output','Test input']:
    print('==',name)
    for c,cells in comps(G[name]):
        print(c, shape(cells), len(cells), cells[:3])

import json
def transform(g):
    g=[row[:] for row in g]
    cs=comps(g)
    groups={}
    for c,cells in cs:
        groups.setdefault(shape(cells),[]).append((c,cells))
    for sh,objs in groups.items():
        if len(objs)>1:
            win=max(c for c,_ in objs)
            for c,cells in objs:
                if c!=win:
                    for y,x in cells: g[y][x]=win
    return g
